package com.bank.sip.repository;

import com.bank.sip.model.SipInvestment;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.math.BigDecimal;
import java.util.List;

public interface SipRepository extends JpaRepository<SipInvestment, String> {

    // Derived query: Spring generates SQL from method name
    List<SipInvestment> findByAccountIdAndStatus(String accountId, String status);

    // JPQL aggregate
    @Query("SELECT SUM(s.currentValue) FROM SipInvestment s WHERE s.accountId = :accountId AND s.status = 'ACTIVE'")
    BigDecimal sumCurrentValueByAccount(String accountId);
}
